 const rows=await response.json(),c=rows?.[0]?.catalog;if(!c?.helpers||!c?.columns)throw Error('Supplement shape unavailable');const file=`${root}/FVI-GOVERNANCE-CATALOG-${environment}-SUPPLEMENT-20261002.json`,bytes=JSON.stringify({at:new Date().toISOString(),ref,read_only:true,query_sha256:createHash('sha256').update(query).digest('hex'),rows},null,2);await writeFile(file,bytes);console.log(JSON.stringify({environment,file,sha256:createHash('sha256').update(bytes).digest('hex'),columns:c.columns.length,helpers:c.helpers.map(f=>f.schema+'.'+f.name),enums:c.enums.length}));
